(function() {
  'use strict';
  var form = document.getElementById('newsletterForm');
  var successMessage = document.getElementById('newsletterSuccess');

  if (form && successMessage) {
    form.addEventListener('submit', function(event) {
      event.preventDefault();
      event.stopPropagation();

      if (form.checkValidity()) {
        // Simulate API call or backend processing
        form.classList.remove('was-validated');
        form.reset();
        form.style.display = 'none'; // Hide the form
        successMessage.classList.remove('d-none'); // Show success message

        // Optionally, hide success message after a few seconds
        setTimeout(function() {
          successMessage.classList.add('d-none');
          form.style.display = 'flex'; // Show form again
        }, 5000);
      } else {
        form.classList.add('was-validated');
      }
    }, false);
  }
})();

