(function() {
  'use strict';
  const form = document.getElementById('multiStepForm');
  const step1 = document.getElementById('step1');
  const step2 = document.getElementById('step2');
  const nextBtn = document.getElementById('nextStep');
  const prevBtn = document.getElementById('prevStep');
  const progressLinks = document.querySelectorAll('#progressIndicator .nav-link');
  let currentStep = 1;

  function updateProgress() {
    progressLinks.forEach(link => {
      const stepNum = parseInt(link.dataset.step);
      if (stepNum === currentStep) {
        link.classList.add('active');
        link.style.backgroundColor = 'var(--sl-primary)';
        link.style.borderColor = 'var(--sl-primary)';
        link.style.color = '#fff';
      } else {
        link.classList.remove('active');
        link.style.backgroundColor = 'var(--sl-card-bg)';
        link.style.borderColor = 'var(--sl-border)';
        link.style.color = 'var(--sl-text-main)';
      }
    });
  }

  function showStep(stepNum) {
    step1.classList.add('d-none');
    step2.classList.add('d-none');
    if (stepNum === 1) {
      step1.classList.remove('d-none');
    } else if (stepNum === 2) {
      step2.classList.remove('d-none');
    }
    currentStep = stepNum;
    updateProgress();
  }

  if (nextBtn) {
    nextBtn.addEventListener('click', function() {
      const inputs = step1.querySelectorAll('input, textarea');
      let allValid = true;
      inputs.forEach(input => {
        if (!input.checkValidity()) {
          allValid = false;
          input.classList.add('is-invalid');
        } else {
          input.classList.remove('is-invalid');
        }
      });

      if (allValid) {
        showStep(2);
      }
    });
  }

  if (prevBtn) {
    prevBtn.addEventListener('click', function() {
      showStep(1);
    });
  }

  if (form) {
    form.addEventListener('submit', function(event) {
      event.preventDefault();
      event.stopPropagation();
      const inputs = step2.querySelectorAll('input, textarea');
      let allValid = true;
      inputs.forEach(input => {
        if (!input.checkValidity()) {
          allValid = false;
          input.classList.add('is-invalid');
        } else {
          input.classList.remove('is-invalid');
        }
      });

      if (allValid) {
        alert('Formulário multi-etapas enviado! (Apenas simulação de UI)');
        form.reset();
        form.classList.remove('was-validated');
        showStep(1); // Reset to first step
      } else {
        form.classList.add('was-validated');
      }
    }, false);
  }

  updateProgress(); // Initial progress state
})();

variante_4.css:
.star-rating {
  display: inline-block;
  font-size: 0;
  direction: rtl; /* Para alinhar estrelas à direita e facilitar o CSS */
}
.star-rating input[type="radio"] {
  display: none;
}
.star-rating label {
  font-size: 2rem;
  color: #ccc; /* Cor da estrela vazia */
  cursor: pointer;
  padding: 0 2px;
  transition: color 0.2s ease-in-out;
}
.star-rating label::before {
  content: '★'; /* Caractere de estrela */
}
.star-rating label:hover,
.star-rating label:hover ~ label,
.star-rating input[type="radio"]:checked ~ label {
  color: var(--sl-accent); /* Cor da estrela preenchida */
}
.star-rating.has-error label {
  color: #ccc; /* Reset color if error is present */
}
.star-rating.has-error label:hover,
.star-rating.has-error label:hover ~ label,
.star-rating.has-error input[type="radio"]:checked ~ label {
  color: var(--sl-accent);
}
#ratingFeedback {
  color: var(--bs-danger);
}
#ratingForm .form-control:focus {
  border-color: var(--sl-primary);
  box-shadow: 0 0 0 0.25rem rgba(var(--sl-primary-rgb), .25);
}

