(function() {
  'use strict';
  const ratingForm = document.getElementById('ratingForm');
  const starRatingContainer = ratingForm ? ratingForm.querySelector('.star-rating') : null;
  const ratingFeedback = document.getElementById('ratingFeedback');
  let selectedRating = 0;

  if (starRatingContainer) {
    starRatingContainer.addEventListener('change', function(event) {
      if (event.target.name === 'rating') {
        selectedRating = parseInt(event.target.value);
        ratingFeedback.classList.add('d-none');
        starRatingContainer.classList.remove('has-error');
      }
    });
  }

  if (ratingForm) {
    ratingForm.addEventListener('submit', function(event) {
      event.preventDefault();
      event.stopPropagation();

      if (selectedRating === 0) {
        ratingFeedback.classList.remove('d-none');
        starRatingContainer.classList.add('has-error');
      } else {
        ratingFeedback.classList.add('d-none');
        starRatingContainer.classList.remove('has-error');
        const comment = document.getElementById('commentText').value;
        alert(`Avaliação enviada: ${selectedRating} estrelas. Comentário: "${comment}" (Apenas simulação de UI)`);
        ratingForm.reset();
        selectedRating = 0;
        // Reset star visual state
        const checkedStar = starRatingContainer.querySelector('input[type="radio"]:checked');
        if (checkedStar) checkedStar.checked = false;
      }
    });
  }
})();
